def main():
    print(f"NLE Topics Count: {len(NLE_TOPICS)}")
    print(f"MRCEM Topics Count: {len(MRCEM_TOPICS)}")
    print(f"SMLE Topics Count: {len(SMLE_TOPICS)}")

    assert len(NLE_TOPICS) == 100
    assert len(MRCEM_TOPICS) == 100
    assert len(SMLE_TOPICS) == 100

    for name, lst in [("NLE", NLE_TOPICS), ("MRCEM", MRCEM_TOPICS), ("SMLE", SMLE_TOPICS)]:
        for i, t in enumerate(lst):
            assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at {name} #{i}: {t[0]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at {name} #{i}: {t[0]}"
            assert t[5].startswith("https://"), f"Invalid URL at {name} #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega117_topics.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 117 topics (NLE 100, MRCEM 100, SMLE 100)\n\n")
        f.write(f"NLE_TOPICS = {json.dumps(NLE_TOPICS, indent=2)}\n\n")
        f.write(f"MRCEM_TOPICS = {json.dumps(MRCEM_TOPICS, indent=2)}\n\n")
        f.write(f"SMLE_TOPICS = {json.dumps(SMLE_TOPICS, indent=2)}\n")

    print(f"Saved Mega-Batch 117 topics to {out_path}!")

if __name__ == "__main__":
    main()
